package br.com.cineo;
import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
import static br.com.cineo.MainActivity.*;
/** One startup response; first page visible immediately, next pages only on demand. */
class FastHome {
 final MainActivity a;LinearLayout content,more;JSONArray items=new JSONArray();long next=0;String genre="Todos",scope="";int scrollY=0;boolean rendered=false;
 FastHome(MainActivity activity){a=activity;}
 void remember(){if(a.screen.equals("home")&&a.body!=null&&a.body.getParent() instanceof ScrollView)scrollY=((ScrollView)a.body.getParent()).getScrollY();}
 void open(){if(!scope.equals(a.fastCache.scope())){scope=a.fastCache.scope();scrollY=0;genre="Todos";items=new JSONArray();next=0;}rendered=false;a.page("home","","",0,null);HorizontalScrollView horizontal=new HorizontalScrollView(a);horizontal.setHorizontalScrollBarEnabled(false);LinearLayout chips=a.row();horizontal.addView(chips);a.body.addView(horizontal);for(String value:new String[]{"Todos","Drama","Romance","Suspense","Ação","Comédia","Novela"}){TextView chip=a.label(value,12,WHITE);chip.setPadding(a.dp(14),a.dp(10),a.dp(14),a.dp(10));chip.setBackground(a.bg(value.equals(genre)?RED:CARD,20));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.rightMargin=a.dp(8);chips.addView(chip,p);chip.setOnClickListener(v->{genre=value;scrollY=0;rendered=false;for(int i=0;i<chips.getChildCount();i++)chips.getChildAt(i).setBackground(a.bg(chips.getChildAt(i)==chip?RED:CARD,20));render();});}a.gap(a.body,14);content=a.col();a.body.addView(content);more=a.col();a.body.addView(more);a.text(content,"Suas histórias estarão aqui. O conteúdo recente fica salvo neste aparelho.",14,MUTED);a.readFlow.get("/v9/start",r->{apply(r);JSONArray incoming=r.getJSONArray("items");boolean extended=items.length()>incoming.length();if(extended){Set<Integer> ids=new HashSet<>();for(int i=0;i<incoming.length();i++)ids.add(incoming.getJSONObject(i).optInt("id"));for(int i=0;i<items.length();i++)if(ids.add(items.getJSONObject(i).optInt("id")))incoming.put(items.getJSONObject(i));}items=incoming;if(!extended)next=r.optLong("next_before",0);render();},true);a.button(a.body,"Atualizar catálogo",BG,()->{a.fastCache.force=true;open();});a.pro.flushProgress(()->{});}
 void apply(JSONObject r)throws Exception{JSONObject profile=r.optJSONObject("profile");if(profile!=null){JSONObject viewer=profile.optJSONObject("viewer");if(viewer!=null){a.viewerKids=viewer.optBoolean("kids");a.viewerMaxRating=viewer.optInt("max_rating",18);a.viewerName=viewer.optString("name");a.prefs.edit().putBoolean(a.uid+":viewer_kids",a.viewerKids).putInt(a.uid+":viewer_max_rating",a.viewerMaxRating).putString(a.uid+":viewer_name",a.viewerName).apply();}a.prefs.edit().putString(a.local("name"),profile.optString("name","Criador")).putString(a.local("avatar"),profile.optString("avatar")).apply();}JSONObject pref=r.optJSONObject("preferences");if(pref!=null){a.complete.preferences=pref.optJSONArray("genres");if(a.complete.preferences==null)a.complete.preferences=new JSONArray();a.complete.pendingOnboarding=!pref.optBoolean("onboarded");}a.pro.importProgress(r.optJSONArray("progress"));a.pro.homeData=r.optJSONObject("editorial")==null?new JSONObject():r.getJSONObject("editorial");a.discovery.home=r.optJSONObject("discovery")==null?new JSONObject():r.getJSONObject("discovery");JSONObject experience=r.optJSONObject("experience");if(experience!=null){a.libraryHub.homeBootstrap=experience;a.libraryHub.applySettings(experience);a.libraryHub.recommended=experience.optJSONArray("recommendations");if(a.libraryHub.recommended==null)a.libraryHub.recommended=new JSONArray();JSONArray choices=experience.optJSONArray("choices");if(choices!=null)for(int i=0;i<choices.length();i++){JSONObject choice=choices.getJSONObject(i);a.prefs.edit().putBoolean(a.local("hide_resume_"+choice.optInt("show_id")),choice.optBoolean("hide_resume")).apply();}}}
 void render(){if(rendered)scrollY=((ScrollView)a.body.getParent()).getScrollY();rendered=true;content.removeAllViews();a.renderCatalog(content,items,"",genre,false);more.removeAllViews();if(next>0)a.button(more,"Carregar mais histórias",CARD,()->a.readFlow.get("/v9/catalog?before="+next,r->{JSONArray values=r.getJSONArray("items");Set<Integer> ids=new HashSet<>();for(int i=0;i<items.length();i++)ids.add(items.getJSONObject(i).optInt("id"));for(int i=0;i<values.length();i++)if(ids.add(values.getJSONObject(i).optInt("id")))items.put(values.getJSONObject(i));next=r.optLong("next_before",0);render();}));ScrollView scroll=(ScrollView)a.body.getParent();int y=scrollY;scroll.post(()->scroll.scrollTo(0,y));}
}
